import { tripleapilogDetail } from "@/api/logs";
export default {
  props: ['isShow', 'itemId'],
  data: function data() {
    return {
      formItemList: [{
        label: 'ID',
        prop: 'id',
        value: ''
      }, {
        label: '类名',
        prop: 'className',
        value: ''
      }, {
