      }, {
        label: '方法名',
        prop: 'methodName',
        value: ''
      }, {
        label: '用户区域名称',
        prop: 'regionName',
        value: ''
      }, {
        label: '返回结果',
        prop: 'result',
        value: ''
      }, {
        label: '开始时间',
        prop: 'startTime',
        value: ''
      }, {
        label: '是否成功',
        prop: 'success',
        value: ''
      }, {
        label: '参数值',
        prop: 'text',
        value: ''
      }, {
        label: '三方系统',
        prop: 'tripleType',
        value: ''
      }, {
        label: '操作类型',
        prop: 'value',
        value: ''
      }],
      threeLogDetail: {}
    };
  },
  mounted: function mounted() {
    this.getDetail();
  },
  methods: {
    getDetail: function getDetail() {
      var _this = this;
      tripleapilogDetail({
        id: this.itemId
      }).then(function (res) {
        _this.threeLogDetail = res.data;
        _this.threeLogDetail.text = JSON.parse(_this.threeLogDetail.text);
        for (var i = 0; i < _this.formItemList.length; i++) {
          var item = _this.formItemList[i];
          if (item.label == '是否成功') {
            _this.threeLogDetail[item.prop] = _this.threeLogDetail[item.prop] == 1 ? '失败' : '成功';
          }
          item.value = _this.threeLogDetail[item.prop];
        }
      });
    }
  }
};
